package com.ruoyi.kangaroo.ext.community;
import static com.ruoyi.kangaroo.ext.KgJdbc.p;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.junit.jupiter.api.*;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.mock.web.MockMultipartFile;
import org.springframework.aop.framework.ProxyFactory;import org.springframework.transaction.*;import org.springframework.transaction.interceptor.TransactionInterceptor;import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import com.ruoyi.kangaroo.ext.KgJdbc;import com.ruoyi.common.exception.ServiceException;import java.util.*;
class KgChatImageMessageTest {
 KgJdbc db=mock(KgJdbc.class);KgChatService service=new KgChatService();KgCommunityGuard guard=mock(KgCommunityGuard.class);String key="m0123456789abcdef";byte[] bytes;
 @BeforeEach void setup()throws Exception{bytes=KgChatMediaCandidateTest.png();ReflectionTestUtils.setField(service,"db",db);
        when(db.one(startsWith("select config_value from sys_config"), anyMap())).thenReturn(p("configValue", "true"));ReflectionTestUtils.setField(service,"guard",guard);when(db.one(startsWith("select status, del_flag"),anyMap())).thenReturn(p("status","0","delFlag","0"));when(db.one(startsWith("select * from kg_chat_member"),anyMap())).thenReturn(p("role","member"));when(db.must(startsWith("select * from kg_chat_conv"),anyMap(),anyString())).thenReturn(p("convId",12L,"convType","group","status","active","title","test"));when(db.claimIdem(anyString(),anyString())).thenReturn(true);when(db.insert(eq("kg_chat_msg"),anyMap())).thenReturn(73L);when(db.update(startsWith("insert into kg_chat_image"),anyMap())).thenReturn(1);when(db.update(startsWith("update kg_idempotency set biz_id"),anyMap())).thenReturn(1);}
 MockMultipartFile f(){return new MockMultipartFile("file","pic.png","image/png",bytes);}
 void duplicate(String hash){when(db.claimIdem(anyString(),anyString())).thenReturn(false);when(db.one(startsWith("select biz_type, biz_id"),anyMap())).thenReturn(p("bizType","chat_message","bizId",73L));when(db.one(startsWith("select msg_id, conv_id"),anyMap())).thenReturn(p("msgId",73L,"convId",12L,"senderId",7L,"content","[图片]","inputSha",hash));}
 @Test void imageAndMessageThenIdempotencyBindInSameMethod(){assertEquals(73L,service.sendImage(7L,12L,key,f()).get("msgId"));org.mockito.InOrder o=inOrder(db);o.verify(db).insert(eq("kg_chat_msg"),anyMap());o.verify(db).update(startsWith("insert into kg_chat_image"),argThat(m->m.get("b") instanceof byte[]&&"image/png".equals(m.get("t"))));o.verify(db).update(startsWith("update kg_idempotency set biz_id"),anyMap());}
 @Test void exactRetryReturnsSameMessageNoInsert()throws Exception{duplicate(KgChatImage.sha(bytes));assertEquals(73L,service.sendImage(7L,12L,key,f()).get("msgId"));verify(db,never()).insert(anyString(),anyMap());verify(db,never()).update(anyString(),anyMap());}
 @Test void sameKeyDifferentImageConflicts(){duplicate("ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");assertEquals(409,assertThrows(ServiceException.class,()->service.sendImage(7L,12L,key,f())).getCode());verify(db,never()).insert(anyString(),anyMap());}
 @Test void textImageBothDirectionsConflict()throws Exception{duplicate(KgChatImage.sha(bytes));assertEquals(409,assertThrows(ServiceException.class,()->service.send(7L,12L,"[图片]",key)).getCode());duplicate(null);assertEquals(409,assertThrows(ServiceException.class,()->service.sendImage(7L,12L,key,f())).getCode());}
 @Test void imageInsertFailureRollsBackSpringTransaction(){when(db.update(startsWith("insert into kg_chat_image"),anyMap())).thenReturn(0);PlatformTransactionManager tm=mock(PlatformTransactionManager.class);TransactionStatus tx=mock(TransactionStatus.class);when(tm.getTransaction(any())).thenReturn(tx);ProxyFactory p=new ProxyFactory(service);p.setProxyTargetClass(true);p.addAdvice(new TransactionInterceptor(tm,new AnnotationTransactionAttributeSource()));assertEquals(503,assertThrows(ServiceException.class,()->((KgChatService)p.getProxy()).sendImage(7L,12L,key,f())).getCode());verify(tm).rollback(tx);verify(tm,never()).commit(any());verify(db,never()).update(startsWith("update kg_idempotency set biz_id"),anyMap());}
 @Test void noKeyAndClosedConversationNeverStoreImage(){assertEquals(422,assertThrows(ServiceException.class,()->service.sendImage(7L,12L,null,f())).getCode());when(db.must(startsWith("select * from kg_chat_conv"),anyMap(),anyString())).thenReturn(p("convId",12L,"convType","group","status","closed"));assertThrows(ServiceException.class,()->service.sendImage(7L,12L,key,f()));verify(db,never()).insert(anyString(),anyMap());}
 @Test void missingRecalledOrDeletedSenderBinaryNeverReturned(){when(db.one(startsWith("select m.sender_id,i.mime"),anyMap())).thenReturn(null);assertEquals(404,assertThrows(ServiceException.class,()->service.image(7L,12L,73L)).getCode());verify(db).one(argThat(q->q.startsWith("select m.sender_id,i.mime")&&q.contains("u.status='0'")&&q.contains("u.del_flag='0'")&&q.contains("m.status='visible'")),eq(p("m",73L,"c",12L)));}
 @Test void binaryDownloadRechecksBlock(){when(db.one(startsWith("select m.sender_id,i.mime"),anyMap())).thenReturn(p("senderId",8L,"mime","image/png","imageBytes",bytes));doThrow(new ServiceException("blocked",403)).when(guard).requireNotBlocked(7L,8L);assertEquals(403,assertThrows(ServiceException.class,()->service.image(7L,12L,73L)).getCode());}

 void onlineReceiverFixture(boolean muted){
  KgChatReception reception=mock(KgChatReception.class);ReflectionTestUtils.setField(service,"reception",reception);
  Map<String,Object> conv=p("convId",12L,"convType","store","status","active","title","test","storeId",22L,"pairKey","o22-u7","source","online_task");
  when(db.must(startsWith("select * from kg_chat_conv"),anyMap(),anyString())).thenReturn(conv);
  when(db.one(startsWith("select c.conv_type, c.store_id"),anyMap())).thenReturn(conv);
  when(reception.isOnline(anyMap())).thenReturn(true);when(reception.staff(22L,true)).thenReturn(Arrays.asList(8L));
  final boolean[] seated={false};
  when(db.update(startsWith("insert into kg_chat_member"),anyMap())).thenAnswer(i->{Map<String,Object> m=i.getArgument(1);assertEquals(8L,m.get("u"));assertEquals(12L,m.get("c"));assertEquals("store",m.get("r"));String sql=i.getArgument(0);assertFalse(sql.contains("muted"));seated[0]=true;return 1;});
  when(db.list(startsWith("select app_user_id, role from kg_chat_member"),anyMap())).thenAnswer(i->{String sql=i.getArgument(0);assertTrue(sql.contains("muted = '0'"));return seated[0]&&!muted?Arrays.asList(p("appUserId",8L,"role","store")):Collections.emptyList();});
 }
 @Test void newReceiverWithoutOldSeatReceivesNotificationOnNextMessage(){
  onlineReceiverFixture(false);assertEquals(73L,service.sendImage(7L,12L,key,f()).get("msgId"));
  org.mockito.InOrder o=inOrder(db);o.verify(db).must(startsWith("select * from kg_chat_conv"),anyMap(),anyString());o.verify(db).update(startsWith("insert into kg_chat_member"),eq(p("c",12L,"u",8L,"r","store")));o.verify(db).list(startsWith("select app_user_id, role from kg_chat_member"),anyMap());
  verify(db).update(startsWith("insert into kg_message"),argThat(m->Long.valueOf(8).equals(m.get("u"))&&"staff".equals(m.get("m"))));
 }
 @Test void receiverSeatRefreshPreservesMuteAndReplayHasNoSideEffect()throws Exception{
  // 免打扰的收件人不写站内信；2026-10-15 起发送人自己有一行已读记录，所以 kg_message 只写给发送人
  onlineReceiverFixture(true);service.sendImage(7L,12L,key,f());verify(db).update(startsWith("insert into kg_chat_member"),anyMap());verify(db,never()).update(startsWith("insert into kg_message"),argThat(m->Long.valueOf(8).equals(m.get("u"))));
  verify(db,times(1)).update(startsWith("insert into kg_message"),anyMap());verify(db).update(startsWith("insert into kg_message"),argThat(m->Long.valueOf(7).equals(m.get("u"))&&"1".equals(m.get("f"))&&"user".equals(m.get("m"))));
  reset(db);setupForReplay();duplicate(KgChatImage.sha(bytes));assertEquals(73L,service.sendImage(7L,12L,key,f()).get("msgId"));verify(db,never()).update(startsWith("insert into kg_chat_member"),anyMap());
 }
 void setupForReplay(){when(db.one(startsWith("select status, del_flag"),anyMap())).thenReturn(p("status","0","delFlag","0"));when(db.one(startsWith("select * from kg_chat_member"),anyMap())).thenReturn(p("role","member"));when(db.must(startsWith("select * from kg_chat_conv"),anyMap(),anyString())).thenReturn(p("convId",12L,"convType","store","status","active","title","test","storeId",22L,"pairKey","o22-u7","source","online_task"));}

 @Test void senderAndOtherReceiverNeverOverwriteApplicantSeatAndApplicantNoticeStaysUser(){for(long sender:new long[]{7L,8L}){onlineReceiverFixture(false);KgChatReception reception=(KgChatReception)ReflectionTestUtils.getField(service,"reception");when(reception.staff(22L,true)).thenReturn(Arrays.asList(7L,8L));when(db.update(startsWith("insert into kg_chat_member"),anyMap())).thenReturn(1);when(db.one(startsWith("select * from kg_chat_member"),anyMap())).thenReturn(p("role",sender==7?"member":"store"));when(db.list(startsWith("select app_user_id, role from kg_chat_member"),anyMap())).thenReturn(sender==8?Arrays.asList(p("appUserId",7L,"role","member")):Collections.emptyList());service.sendImage(sender,12L,key,f());verify(db,never()).update(startsWith("insert into kg_chat_member"),argThat(m->Long.valueOf(7).equals(m.get("u"))));if(sender==8)verify(db).update(startsWith("insert into kg_message"),argThat(m->Long.valueOf(7).equals(m.get("u"))&&"user".equals(m.get("m"))));clearInvocations(db);}}
 @Test void applicantAsOnlyConfiguredEmployeeStillSeesNoOtherReceiver(){onlineReceiverFixture(false);KgChatReception reception=(KgChatReception)ReflectionTestUtils.getField(service,"reception");when(reception.staff(22L,true)).thenReturn(Arrays.asList(7L));assertTrue(String.valueOf(service.conversation(7L,12L).get("receptionNotice")).contains("暂无可用接待账号"));}
}
